func tileLine(r1, c1, r2, c2) = {
  local points = []
  local dr = abs(r2-r1)
  local dc = abs(c2-c1)
  local sr = if (r1<r2) 1 else -1
  local sc = if (c1<c2) 1 else -1
  local err = dr - dc
  local r = r1
  local c = c1
  while (true) {
    points.add([r,c])
    if (r==r2 && c==c2) { r = r2+1 }
    else {
      local e2 = 2*err
      if (e2 > -dc) { err=err-dc r=r+sr }
      if (e2 < dr) { err=err+dr c=c+sc }
    }
  }
  points
}
