func clearFullRows(board, size) = {
  local b = copyList(board)
  local changed = true
  while (changed) {
    changed = false
    for (r: 1 .. b.listLen()) {
      local full = true
      for (c: 1 .. size) {
        if (b[r][c] == 0) { full = false }
      }
      if (full) {
        b.remove(r)
        local emptyRow = []
        for (c: 1 .. size) { emptyRow.add(0) }
        b.insert(1, emptyRow)
        changed = true
      }
    }
  }
  b
}
