func applyAreaEffect(grid, centerR, centerC, radius, effectFn, size) {
  for (r: 1 .. size) {
    for (c: 1 .. size) {
      if (abs(r-centerR)+abs(c-centerC) <= radius) {
        grid[r][c] = effectFn(grid[r][c])
      }
    }
  }
}
